return ['x-generator'=>'GlotPress/4.0.3','translation-revision-date'=>'2026-08-11 19:50:07+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - Ultimate Addons for Elementor - Stable (latest release)','language'=>'es','messages'=>['%s Widget'=>'Widget %s','Use %s widget and other UAE Pro features to extend your toolbox with more control and flexibility.'=>'Usa el widget %s y otras características de UAE Pro para ampliar tu caja de herramientas con más control y flexibilidad.','Skip to main content'=>'Ir al contenido principal','Invalid parameters.'=>'Parámetros no válidos.','Request failed.'=>'La solicitud ha fallado.','Remote request failed.'=>'La solicitud remota ha fallado.','Invalid or missing nonce.'=>'El nonce no es válido o falta.','BLOCKED: The ability "%1$s" has been disabled by the site administrator. Do NOT retry. Tell the user to enable it in UAE Settings → AI Tools at %2$s'=>'BLOQUEADO: El administrador del sitio ha desactivado la función «%1$s». NO lo intentes de nuevo. Dile al usuario que la active en Configuración de UAE → Herramientas de IA en %2$s','BLOCKED: Modifications are disabled by the site administrator. Do NOT attempt to enable this yourself. Tell the user: "Allow Modifications" must be turned on in UAE Settings → AI Tools at %s'=>'BLOQUEADO: El administrador del sitio ha desactivado las modificaciones. NO intentes activarlas tú mismo. Dile al usuario: «Permitir modificaciones» debe estar activado en Configuración de UAE → Herramientas de IA en %s','Modifications disabled in AI Tools settings.'=>'Las modificaciones están desactivadas en la configuración de «Herramientas de IA».','You are not allowed to edit this post.'=>'No puedes editar esta publicación.','Ability "%s" not found.'=>'No se ha encontrado la habilidad «%s».','Ability "%1$s" is currently disabled. Enable it in AI Tools settings: %2$s'=>'La función «%1$s» está desactivada ahora mismo. Actívala en la configuración de Herramientas de IA: %2$s','Ability "%1$s" requires "Allow Modifications" to be enabled. Turn it on at: %2$s'=>'La habilidad «%1$s» requiere que la opción «Permitir modificaciones» esté activada. Actívala en: %2$s','Ability "%1$s" already registered by "%3$s"; ignoring duplicate registration from "%2$s".'=>'La habilidad «%1$s» ya está registrada por «%3$s»; se ignora el registro duplicado de «%2$s».','Invalid ability handler: it must implement get_name(), get_registration_args(), and execute().'=>'Manejador de habilidades no válido: debe implementar get_name(), get_registration_args() y execute().','Optional. Filter to a single widget slug.'=>'Opcional. Filtra por el slug de un solo widget.','Returns site-wide usage counts for HFE widgets across all Elementor content (pages, posts, and templates).'=>'Muestra las estadísticas de uso de los widgets de HFE en todo el sitio, en todo el contenido de Elementor (páginas, entradas y plantillas).','Get Widget Usage Map'=>'Consigue el mapa de uso del widget','Lists all available widgets with their enabled/disabled status, slug, title, and category.'=>'Muestra todos los widgets disponibles con su estado (activado/desactivado), slug, título y categoría.','List Widgets'=>'Widgets de lista','Disable widgets not used in any published Elementor content (pages, posts, or templates).'=>'Desactiva los widgets que no se utilicen en ningún contenido publicado con Elementor (páginas, entradas o plantillas).','Deactivate Unused Widgets'=>'Desactiva los widgets que no uses','Widget deactivated.'=>'Widget desactivado.','Widget slug to deactivate.'=>'Slug del widget que quieres desactivar.','Disable a specific widget by slug.'=>'Desactiva un widget concreto por slug.','Deactivate Widget'=>'Desactivar el widget','Whether to activate or deactivate all widgets.'=>'Si quieres activar o desactivar todos los widgets.','Activate or deactivate all widgets at once. When activating, Pro widgets are skipped. When deactivating, all widgets are disabled which may break the frontend.'=>